_ROUTES = json.loads(zlib.decompress(base64.b85decode(_ROUTES_DATA)).decode("utf-8"))

def _get(value, key, default=None):
    """Read both normal dictionaries and Kaggle observation objects."""
    if isinstance(value, dict):
        return value.get(key, default)
    getter = getattr(value, "get", None)
    if callable(getter):
        return getter(key, default)
    return getattr(value, key, default)


def route_index(observation, max_shops=2):
    """Choose a tape using zero, one, or two revealed shops."""
    step = _get(observation, "step")
    if step is None:
        step = int(_get(observation, "day", 0) or 0) * 24 + int(
            _get(observation, "hour", 0) or 0
        )
    step = int(step)
    town = _get(observation, "town", {}) or {}
    shops = list(_get(town, "unlocked_shops", []) or [])

    if max_shops >= 2 and step >= SECOND_BRANCH_STEP and len(shops) >= 2:
        return SECOND_ROUTES.get(f"{shops[0]}__{shops[1]}", 0)
    if max_shops >= 1 and step >= FIRST_BRANCH_STEP and shops:
        return FIRST_ROUTES.get(str(shops[0]), 0)
    return 0


def _pass_action(observation):
    player = int(_get(observation, "player", 0) or 0)
    farms = list(_get(observation, "farms", []) or [])
    hands = list(_get(farms[player], "hands", []) or []) if player < len(farms) else []
    return {"farmer": ["PASS"], "hands": [["PASS"] for _ in hands], "market": []}


def action_for_depth(observation, max_shops=2):
    """Return the recorded action while using at most max_shops branches."""
    try:
        raw_step = _get(observation, "step")
        step = int(raw_step) if raw_step is not None else (
            int(_get(observation, "day", 0) or 0) * 24
            + int(_get(observation, "hour", 0) or 0)
        )
        step = min(max(step, 0), 718)
        action = copy.deepcopy(_ROUTES[route_index(observation, max_shops)][step])

        # A tape may have been recorded with a different number of hired hands.
        player = int(_get(observation, "player", 0) or 0)
        farms = list(_get(observation, "farms", []) or [])
        expected = len(_get(farms[player], "hands", []) or []) if player < len(farms) else 0
        hands = list(action.get("hands") or [])
        hands.extend([["PASS"] for _ in range(max(0, expected - len(hands)))])
        action["hands"] = hands[:expected]
        return action
    except Exception:
        return _pass_action(observation)


def agent(observation, configuration=None):
    """Kaggle entry point for the two-shop version."""
    del configuration
    return action_for_depth(observation, max_shops=2)


main = agent
